package service
import("testing";"time";"ballast-watch/internal/model";"ballast-watch/internal/store")
func TestBug29_WarnDoesNotBlockCycleRelease(t *testing.T){svc:=ballastTestServices(t);v:=mustVessel(t,svc);tank:=mustTank(t,svc,v);alertStore:=store.NewComplianceComplianceAlertStore(svc.Store);if err:=alertStore.Create(ballastCtx(),&model.ComplianceAlert{BallastTankID:tank.ID,SamplingPointID:1,Level:model.ComplianceAlertWarn,Status:model.ComplianceAlertOpen,OpenedAt:time.Now()});err!=nil{t.Fatal(err)};cycle,err:=svc.TreatmentCyclees.Start(ballastCtx(),&model.TreatmentCycleInput{BallastTankID:tank.ID,Name:"cycle",Product:"ballast",Phase:"treat"});if err!=nil{t.Fatal(err)};if _,err=svc.TreatmentCyclees.Complete(ballastCtx(),cycle.ID);err!=nil{t.Fatal(err)};got,_:=svc.BallastTanks.Get(ballastCtx(),tank.ID);if got.Status!=model.StateRelease{t.Fatalf("warn blocked release: %s",got.Status)}}
